INSERT INTO collection_pages VALUES('8af6d1774ef9d632daa63a20b3cec9c5563814244fabb44f87c4f5c8d39f398b','f1e5d4af0e809872f073d7d7a9d25182d9dd1c65bb7655fcc96e3beb1d7cafd5','{"hasNext":false,"items":[{"author":{"account":null,"email":"chau.vukiet@kingfoodmart.net","name":"Chau Vu Kiet"},"authoredDate":"2026-08-24T03:41:36Z","committedDate":"2026-08-24T03:41:36Z","committer":{"account":null,"email":"chau.vukiet@kingfoodmart.net","name":"Chau Vu Kiet"},"observedAt":"2026-10-09T00:21:24.946Z","repositoryId":1344494941,"sha":"622dd7ff6f31aed2633e3b8cabfcb313404d6e64"}],"observedAt":"2026-10-09T00:21:24.946Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/KietMm/KietMm/commits/622dd7ff6f31aed2633e3b8cabfcb313404d6e64/comments","commit":{"author":{"date":"2026-08-24T03:41:36Z","email":"chau.vukiet@kingfoodmart.net","name":"Chau Vu Kiet"},"comment_count":0,"committer":{"date":"2026-08-24T03:41:36Z","email":"chau.vukiet@kingfoodmart.net","name":"Chau Vu Kiet"},"message":"Add profile README\n\nGitHub renders the README of the repo whose name matches the username at the\ntop of the profile. The work described in the CV is closed source, so this is\nthe only place on the profile where it can be stated.\n\nBanner and content are generated from src/data/cv.ts in KietMm/PROFILE via\nnpm run profile, so they cannot drift from the CV.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"4fb66d8557aa24cc9b835a26909f8ed56ad5d871","url":"https://api.github.com/repos/KietMm/KietMm/git/trees/4fb66d8557aa24cc9b835a26909f8ed56ad5d871"},"url":"https://api.github.com/repos/KietMm/KietMm/git/commits/622dd7ff6f31aed2633e3b8cabfcb313404d6e64","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/KietMm/KietMm/commit/622dd7ff6f31aed2633e3b8cabfcb313404d6e64","node_id":"C_kwDOUCNdXdoAKDYyMmRkN2ZmNmYzMWFlZDI2MzNlM2I4Y2FiZmNiMzEzNDA0ZDZlNjQ","parents